9	// Server-side cache for the agent-pushed review. Storybook's dev server is
10	// long-lived; this single slot survives across reconnecting browser tabs and
11	// is what REQUEST_REVIEW replays. It is intentionally not persisted to disk —
12	// a dev-server restart wipes the slate.
13	let cached: ReviewState | undefined;
14	let latestPushSeq = 0;
15	
16	/** Test-only: reset the module-level cache between cases. */
17	export function __resetCache(): void {
18	  cached = undefined;
19	  latestPushSeq = 0;
20	}
