22	async function enrichWithBranch(
23	  payload: ReviewState,
24	  resolveBranch: (cwd: string) => Promise<string | undefined>
25	): Promise<ReviewState> {
26	  const branchName = await resolveBranch(process.cwd());
27	  const enriched: ReviewState = {
28	    ...payload,
29	    // branchName is server-resolved; overwrite any agent-supplied value so an
30	    // unresolvable local branch can't leave a spoofed branch in the payload.
31	    branchName,
32	    // Server-side timestamp is authoritative for "Created x minutes ago".
33	    createdAt: Date.now(),
34	  };
35	  if (enriched.branchName === undefined) {
36	    delete enriched.branchName;
37	  }
38	  return enriched;
39	}
