41	export interface ServerChannelOptions {
42	  /** Override the git-branch resolver. Used by tests. */
43	  resolveBranch?: (cwd: string) => Promise<string | undefined>;
44	}
45	
46	/**
47	 * Storybook's preset hook that hands us the long-lived dev-server channel.
48	 *
49	 * Responsibilities:
50	 * - PUSH_REVIEW (from @storybook/addon-mcp): enrich with git branchName,
51	 *   cache, broadcast as DISPLAY_REVIEW so any open tab updates.
52	 * - REQUEST_REVIEW (from a tab that just mounted): re-broadcast the cached
53	 *   payload as DISPLAY_REVIEW so the late tab catches up.
54	 */
55	export const experimental_serverChannel = async (
56	  channel: Channel,
57	  _options: Options,
58	  serverOptions: ServerChannelOptions = {}
59	) => {
60	  const resolveBranch = serverOptions.resolveBranch ?? currentGitBranch;
61	
62	  channel.on(EVENTS.PUSH_REVIEW, async (payload: ReviewState) => {
63	    const seq = ++latestPushSeq;
64	    const enriched = await enrichWithBranch(payload, resolveBranch);
65	    if (seq !== latestPushSeq) {
66	      return;
67	    }
68	    cached = enriched;
69	    channel.emit(EVENTS.DISPLAY_REVIEW, enriched);
70	  });
71	
72	  channel.on(EVENTS.REQUEST_REVIEW, () => {
73	    if (cached) {
74	      channel.emit(EVENTS.DISPLAY_REVIEW, cached);
75	    }
76	  });
77	
78	  return channel;
79	};
