81	const BASELINE_PROXY_PATH = '/__review-baseline';
82	const BASELINE_TARGET_ORIGIN = 'https://next--635781f3500dd2c49e189caf.chromatic.com';
83	
84	export const experimental_devServer = (app: ServerApp) => {
85	  const proxyRequest = createProxyMiddleware({
86	    target: BASELINE_TARGET_ORIGIN,
87	    changeOrigin: true,
88	    // The baseline origin is a remote Chromatic server that can be slow or
89	    // unreachable. Bound the wait and respond deterministically so a dead
90	    // connection fails fast instead of hanging the review UI's baseline iframe.
91	    timeout: 30_000,
92	    proxyTimeout: 30_000,
93	    pathRewrite: (path) =>
94	      path.startsWith(BASELINE_PROXY_PATH) ? path.slice(BASELINE_PROXY_PATH.length) || '/' : path,
95	    on: {
96	      error: (_error, _req, res) => {
97	        // `res` is a net.Socket on WebSocket upgrades; only HTTP responses
98	        // carry a status code.
99	        if ('writeHead' in res) {
100	          if (!res.headersSent) {
101	            res.writeHead(502, { 'Content-Type': 'text/plain' });
102	          }
103	          res.end('Baseline preview is unavailable.');
104	        }
105	      },
106	    },
107	  }) as unknown as Middleware;
108	
109	  app.use(BASELINE_PROXY_PATH, proxyRequest);
110	  return app;
111	};
