1	/**
2	 * The review payload an agent pushes via the `display-review` MCP tool.
3	 *
4	 * Flow:
5	 *   MCP `display-review` tool → emit PUSH_REVIEW on the Storybook channel
6	 *   → this addon's server preset enriches with `branchName` and caches it
7	 *   → emits DISPLAY_REVIEW to all open tabs (or replays on REQUEST_REVIEW).
8	 *
9	 * This mirrors the canonical valibot schema in `@storybook/addon-mcp` →
10	 * `tools/display-review.ts`. This side only renders the data — it does
11	 * not validate — so it needs the type, not the validator. Keep `title` /
12	 * `description` / `collections` in sync with that schema.
13	 */
14	
15	export type CollectionKind = 'atomic' | 'consumer' | 'transitive' | 'catch-all';
16	
17	export interface ReviewCollection {
18	  title: string;
19	  rationale: string;
20	  storyIds: string[];
21	  kind?: CollectionKind;
22	}
23	
24	export interface ReviewState {
25	  title: string;
26	  description: string;
27	  collections: ReviewCollection[];
28	  changedFiles?: string[];
29	  /**
30	   * Current git branch of the target repo, resolved server-side by this
31	   * addon's preset; not part of the agent's MCP payload.
32	   */
33	  branchName?: string;
34	  /**
35	   * Server-side creation timestamp (unix ms) assigned when PUSH_REVIEW is
36	   * received; used for live "Created x minutes ago" UI in the summary.
37	   */
38	  createdAt?: number;
39	  /**
40	   * Whether a baseline is available to compare against. Enables the
41	   * baseline/latest comparison controls on the detail screen. The baseline
42	   * source itself is provided on a separate branch; until then this stays
43	   * unset and the controls are hidden.
44	   */
45	  hasBaseline?: boolean;
46	}
