10	function createMockChannel() {
11	  const listeners = new Map<string, Array<(...args: any[]) => void>>();
12	  const emitted: Array<{ event: string; payload: unknown }> = [];
13	
14	  const channel = {
15	    on: vi.fn((event: string, listener: (...args: any[]) => void) => {
16	      const arr = listeners.get(event) ?? [];
17	      arr.push(listener);
18	      listeners.set(event, arr);
19	    }),
20	    emit: vi.fn((event: string, payload?: unknown) => {
21	      emitted.push({ event, payload });
22	    }),
23	    fire: async (event: string, ...args: unknown[]) => {
24	      const arr = listeners.get(event) ?? [];
25	      for (const listener of arr) {
26	        await listener(...args);
27	      }
28	    },
29	  } as unknown as Channel & {
30	    fire: (event: string, ...args: unknown[]) => Promise<void>;
31	  };
32	
33	  return { channel, emitted };
34	}
