/**
 * Lightweight in-process pub/sub for source-file change notifications.
 *
 * The dev server owns file-system change detection (via the builder's
 * `ChangeDetectionAdapter`). Features that need to react to source edits —
 * such as the review addon marking a cached review as stale — subscribe here
 * rather than each wiring its own watcher. `notifySourceFileChange` is called
 * by the change detector when it observes an add/change/unlink event.
 *
 * This is deliberately module-level (not a class): the dev server is a single
 * long-lived process, so a single shared listener set is the right scope.
 */

export type SourceFileChangeListener = (event: FileChangeEvent) => void;

const listeners = new Set<SourceFileChangeListener>();

/**
 * Register a listener for source-file change events.
 *
 * @returns An unsubscribe function; calling it stops the listener from
 *   receiving any further events. Safe to call more than once.
 */
export function subscribeToSourceFileChanges(listener: SourceFileChangeListener): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/**
 * Deliver a change event to every registered listener.
 *
 * Iterates over a snapshot so a listener that unsubscribes (itself or another)
 * mid-delivery cannot skip a sibling. A throwing listener is isolated: its
 * error is swallowed so it neither aborts delivery to the remaining listeners
 * nor propagates back to the file watcher that triggered the notification.
 */
export function notifySourceFileChange(event: FileChangeEvent): void {
  for (const listener of [...listeners]) {
    try {
      listener(event);
    } catch {
      // A misbehaving subscriber must not break change detection for others.
    }
  }
}

/**
 * Test-only: drop all registered listeners so no events are delivered after a
 * reset. Prefixed `internal_` because it is not part of the stable API.
 */
export function internal_resetSourceFileChangeListeners(): void {
  listeners.clear();
}
