+import { describe, expect, it } from 'vitest';
+import {
+  subscribeToSourceFileChanges,
+  notifySourceFileChange,
+  internal_resetSourceFileChangeListeners,
+} from '/workspace/repo/code/core/src/core-server/change-detection/source-changes.ts';
+
+describe('source-changes', () => {
+  it('delivers to listeners and unsubscribes', () => {
+    internal_resetSourceFileChangeListeners();
+    const seen: any[] = [];
+    const unsub = subscribeToSourceFileChanges((e) => seen.push(e));
+    notifySourceFileChange({ kind: 'change', path: '/a' });
+    unsub();
+    notifySourceFileChange({ kind: 'change', path: '/b' });
+    expect(seen).toEqual([{ kind: 'change', path: '/a' }]);
+  });
+  it('isolates throwing listeners, calls all', () => {
+    internal_resetSourceFileChangeListeners();
+    const seen: string[] = [];
+    subscribeToSourceFileChanges(() => { throw new Error('boom'); });
+    subscribeToSourceFileChanges((e) => seen.push(e.path));
+    expect(() => notifySourceFileChange({ kind: 'add', path: '/x' })).not.toThrow();
+    expect(seen).toEqual(['/x']);
+  });
+  it('reset removes all', () => {
+    internal_resetSourceFileChangeListeners();
+    const seen: string[] = [];
+    subscribeToSourceFileChanges((e) => seen.push(e.path));
+    internal_resetSourceFileChangeListeners();
+    notifySourceFileChange({ kind: 'unlink', path: '/y' });
+    expect(seen).toEqual([]);
+  });
+});
